# Builds GrandPrix.asm: gp_main.s + the kernels + their nop-padded copies (pad.py) + data.
import sys
from pad import pad
from gp_kernels import KERNELS, PAD_RENAME

out = sys.argv[1]
main = open('gp_main.s', encoding='utf-8').read()
padded = pad(KERNELS, PAD_RENAME)
text = (main + KERNELS +
	'\n# ---------------- nop-padded copies (generated by pad.py: 3 nops between dependent instructions,\n'
	'# 2 after every branch / jump). This is the code our pipeline needed before the hazard unit. ----------------\n'
	+ padded + '\n\n.data\nin_data: .space 192\nwork: .space 192\nres: .space 128\nflags: .space 2048\nstack: .space 256\nstack_top: .word 0\n')
open(out, 'w', encoding='utf-8', newline='\n').write(text)
n_fast = sum(1 for l in KERNELS.splitlines() if l and not l.startswith('#') and not l.endswith(':'))
n_pad = sum(1 for l in padded.splitlines() if l and not l.startswith('#') and not l.endswith(':'))
print('kernels: %d instructions -> %d with nops' % (n_fast, n_pad))
